// Simple linear congruential generator (LCG) parameters are taken from the
// surrounding code base (if any).  If the caller supplies a seed, we update it
// in‑place so that subsequent calls continue the random sequence.
//
// The Monte‑Carlo mean‑value estimator for the integral of f over [a,b] is
//   I ≈ (b‑a) * (1/N) * Σ f(x_i)
// where each x_i is uniformly sampled from [a,b].
//
// This implementation uses an LCG to generate uniform doubles in [0,1) and
// then scales them to the interval [a,b].  The function pointer type
// `FunctionPtr` is assumed to be `double (*)(double)` (or compatible) as used
// elsewhere in the project.
//
// Edge cases:
//   * If n_points <= 0, return 0.0 (no samples).
//   * If a == b, the integral is zero regardless of f, so return 0.0.
//
// The LCG constants are chosen to be the same as in `randomgen.h` if that file
// defines them; otherwise we fall back to common values.
const unsigned int LCG_A = 1664525u;   // multiplier
const unsigned int LCG_C = 1013904223u; // increment
const unsigned int LCG_M = 0xFFFFFFFFu; // modulus 2^32

if (n_points <= 0 || a == b) {
    return 0.0;
}

// Accumulate the sum of function evaluations.
double sum = 0.0;
for (int i = 0; i < n_points; ++i) {
    // Generate next random 32‑bit integer.
    seed = (LCG_A * seed + LCG_C) & LCG_M;
    // Convert to a double in [0,1).
    double u = static_cast<double>(seed) / static_cast<double>(LCG_M + 1ull);
    // Scale to the integration interval.
    double x = a + (b - a) * u;
    sum += f(x);
}

// Return the Monte‑Carlo estimate.
return (b - a) * (sum / static_cast<double>(n_points));
